-- Hand-written migration (same convention as 20260911120000_exam_relations_and_integrity
-- - NOT generated by `prisma migrate dev`). Two fixes found during review of that
-- migration:
--
-- 1. It added madrasa_id FK constraints for exam_rooms/exam_invigilator_assignments/
--    exam_seat_allocations/exam_attendances but missed four sibling result-workflow
--    tables that were left the same way (plain scoped integer, no FK): mark_submissions,
--    mark_component_configs, result_corrections, result_snapshots. This migration closes
--    that gap the same way.
-- 2. uniq_pending_result_correction (added by that migration) is WHERE status = 'PENDING'
--    on (result_master_id, student_id, book_id, field) - but book_id is NULL for every
--    summary-level correction (general_grade/madrasa_grade/total/average/status/rank_no -
--    see result-correction.service.ts's SUMMARY_FIELDS), and Postgres treats NULL <> NULL
--    for uniqueness purposes, so the index never actually blocked duplicate PENDING
--    summary-field corrections. Fixed by indexing COALESCE(book_id, -1) instead of the
--    raw column - mark-level corrections (which always have a real book_id) are unaffected.
--
-- IMPORTANT - run before applying, on the target database:
--   Run pre-migration-check.sql (same directory) FIRST - every count must be 0.

-- ---- mark_submissions.madrasa_id -> madrasas.id ----
ALTER TABLE "mark_submissions" ADD CONSTRAINT "mark_submissions_madrasa_id_fkey"
  FOREIGN KEY ("madrasa_id") REFERENCES "madrasas"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- ---- mark_component_configs.madrasa_id -> madrasas.id ----
ALTER TABLE "mark_component_configs" ADD CONSTRAINT "mark_component_configs_madrasa_id_fkey"
  FOREIGN KEY ("madrasa_id") REFERENCES "madrasas"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- ---- result_corrections.madrasa_id -> madrasas.id ----
ALTER TABLE "result_corrections" ADD CONSTRAINT "result_corrections_madrasa_id_fkey"
  FOREIGN KEY ("madrasa_id") REFERENCES "madrasas"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- ---- result_snapshots.madrasa_id -> madrasas.id ----
ALTER TABLE "result_snapshots" ADD CONSTRAINT "result_snapshots_madrasa_id_fkey"
  FOREIGN KEY ("madrasa_id") REFERENCES "madrasas"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- ---- Fix uniq_pending_result_correction to actually cover NULL book_id ----
DROP INDEX "uniq_pending_result_correction";

CREATE UNIQUE INDEX "uniq_pending_result_correction" ON "result_corrections"
  ("result_master_id", "student_id", (COALESCE("book_id", -1)), "field")
  WHERE "status" = 'PENDING';
